import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.StringTokenizer;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int a = Integer.parseInt(st.nextToken());
        int b = Integer.parseInt(st.nextToken());
        int l = Integer.parseInt(st.nextToken()) - 1;
        int r = Integer.parseInt(st.nextToken()) - 1;

        int min = 26;
        for (int p = 'a'; p <= 'z'; p++) {
            int qStart = (char) ('a' + a);
            for (int q = qStart; q <= 'z'; q++) {
                StringBuilder rep = new StringBuilder();
                int idx = 0;
                while (idx++ < a) rep.append((char) ('a' + idx - 1));
                idx = 0;
                while (idx++ < b) rep.append((char) p);

                idx = 0;
                while (idx < a) {
                    boolean[] f = new boolean[26];
                    int j = b;
                    while (j < a + b + idx) {
                        f[rep.charAt(j) - 'a'] = true;
                        j++;
                    }
                    for (int c = 0; c < 26; c++) {
                        if (!f[c]) {
                            rep.append((char) ('a' + c));
                            break;
                        }
                    }
                    idx++;
                }

                idx = 0;
                while (idx++ < b) rep.append((char) q);

                boolean[] flag = new boolean[26];
                if (r - l + 1 >= 100_000) {
                    idx = 0;
                    while (idx < rep.length()) {
                        flag[rep.charAt(idx) - 'a'] = true;
                        idx++;
                    }
                } else {
                    idx = l;
                    while (idx <= r) {
                        flag[rep.charAt(idx % rep.length()) - 'a'] = true;
                        idx++;
                    }
                }

                int cnt = 0;
                for (int i = 0; i < 26; i++) if (flag[i]) cnt++;
                if (cnt < min) min = cnt;
            }
        }
        System.out.println(min);
    }
}
